/* Nội dung cập nhật có chọn lọc 16/10/2026. Giữ ID theo kỹ năng để giữ tiến độ. */
window.LESSON = {"id":"bai03","number":3,"title":"Câu điều kiện if, if-else","story":"Em làm chủ cửa hàng nước","badge":{"icon":"🚪","name":"Người gác cổng"},"skills":["Diễn đạt quy tắc bằng phép so sánh","Viết if và if…else","Kiểm thử dưới, bằng và trên mốc"],"errorTable":[["Máy chưa biết tên biến","Chưa khai báo hoặc gõ khác hoa/thường","Khai báo trước rồi dùng đúng tên."],["Dữ liệu nhập chưa hợp lệ","Bài yêu cầu số nguyên không âm","Nhập đúng số lượng và số giá trị ghi trong đề."],["Kết quả chưa khớp","Phép tính, điều kiện hoặc số lượt chưa đúng","Đối chiếu từng test case; thử đúng mốc trong đề."]],"steps":[{"kind":"stage","id":"stage-1","number":1,"nav":"Đọc điều kiện","kicker":"CHẶNG 1","title":"Đọc điều kiện","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Diễn đạt quy tắc bằng phép so sánh","Phân biệt = và =="],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Em đặt quy ước cho ngày hội: khách mua từ 5 ly được nhận quà. Em cần cho chương trình kiểm tra quy tắc này.</p></div><p>“Từ 5 ly” gồm cả 5, nên viết soLy >= 5. Một phép so sánh cho kết quả đúng hoặc sai. Với cout mặc định, đúng in 1, sai in 0.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>int soLy = 5;
cout &lt;&lt; (soLy &gt;= 5);</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>1</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Chọn điều kiện thể hiện đúng quy tắc nhận quà.</p></div><div style="overflow-x:auto"><table class="tb-table"><thead><tr><th>Ký hiệu</th><th>Đọc là</th><th>Khi soLy = 5</th></tr></thead><tbody><tr><td>></td><td>lớn hơn</td><td>soLy > 5 là sai</td></tr><tr><td>>=</td><td>lớn hơn hoặc bằng</td><td>soLy >= 5 là đúng</td></tr><tr><td><</td><td>nhỏ hơn</td><td>soLy < 5 là sai</td></tr><tr><td><=</td><td>nhỏ hơn hoặc bằng</td><td>soLy <= 5 là đúng</td></tr><tr><td>==</td><td>bằng nhau</td><td>soLy == 5 là đúng</td></tr><tr><td>!=</td><td>khác nhau</td><td>soLy != 5 là sai</td></tr></tbody></table></div><div class="note-card blue"><h3>Phân biệt hai dấu</h3><p><code>soLy = 5;</code> gán số 5 vào biến. <code>soLy == 5</code> hỏi giá trị có bằng 5 không. Học trước >= và > trong quy tắc nhận quà; các dấu còn lại đọc theo bảng khi cần.</p></div>","challenges":[{"id":"s1-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Đủ điều kiện chưa?","prompt":"Máy in gì?","code":"int soLy = 4;
cout << (soLy >= 5);","options":[{"text":"1","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"0"}],"answer":"0","why":"4 chưa đạt 5 nên điều kiện sai, in 0."},{"id":"s1-pick","type":"choice","icon":"🔎","title":"Đến lượt em: Chọn điều kiện","prompt":"Quy ước: mua từ 5 ly được nhận quà. Chọn điều kiện.","options":[{"text":"soLy > 5","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"soLy >= 5"},{"text":"soLy = 5","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"soLy >= 5","why":"Từ 5 gồm đúng 5; dùng >=."}]},{"kind":"stage","id":"stage-2","number":2,"nav":"Thông báo khi đủ điều kiện","kicker":"CHẶNG 2","title":"Thông báo khi đủ điều kiện","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Viết khối if","Xác định lệnh trong và sau khối if"],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Khi khách đủ điều kiện, em muốn chương trình in thông báo nhận quà. Lời cảm ơn luôn xuất hiện.</p></div><p>if đọc là “nếu”. Điều kiện đúng thì thực hiện các lệnh trong { }. Điều kiện sai thì bỏ qua khối đó. Dòng sau dấu } vẫn thực hiện.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>int soLy = 5;
if (soLy &gt;= 5) {
    cout &lt;&lt; "Nhan qua" &lt;&lt; endl;
}
cout &lt;&lt; "Cam on";</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>Nhan qua
Cam on</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Điền điều kiện nhận quà, giữ lời cảm ơn ở ngoài khối if.</p></div><div class="note-card blue"><h3>Dự đoán trước khi chạy</h3><p>Nếu soLy bằng 4, chỉ in Cam on. Nếu bằng 5 hoặc 6, in Nhan qua rồi Cam on. Không đặt dấu ; ngay sau <code>if (...)</code>.</p></div>","challenges":[{"id":"s2-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Khách mua 4 ly","prompt":"Nếu soLy = 4, chương trình ví dụ in gì?","options":[{"text":"Nhan qua
Cam on","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"Cam on"},{"text":"Không in gì","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"Cam on","why":"Điều kiện sai nên bỏ khối if; lời cảm ơn ở sau khối vẫn chạy."},{"id":"s2-code","type":"code","icon":"⌨️","title":"Đến lượt em: Thông báo nhận quà","prompt":"Mã khung đã có lời cảm ơn. Thêm khối if để khách mua từ 5 ly được báo nhận quà.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy;
    cin >> soLy;
    // Them if va dong Nhan qua
    cout << "Cam on";
    return 0;
}
","tests":[{"input":"4","expected":"4
Cam on","pureExpected":"Cam on"},{"input":"5","expected":"5
Nhan qua
Cam on","pureExpected":"Nhan qua
Cam on"},{"input":"6","expected":"6
Nhan qua
Cam on","pureExpected":"Nhan qua
Cam on"}],"inputSpec":{"min":0},"requirements":["Từ 5 ly: in Nhan qua rồi xuống dòng.","Luôn in Cam on sau khối if."],"hints":["Từ 5 ly nghĩa là soLy >= 5.","if (soLy >= 5) { cout << "Nhan qua" << endl; }"],"why":"Kết quả khớp các test case. Hãy giải thích dòng lệnh em vừa hoàn thiện.","rules":[{"test":(function anonymous(code
) {
return new RegExp("if\s*\(").test(window.CPP.stripComments(code));
}),"msg":"Hãy dùng lệnh if để kiểm tra điều kiện."}]}]},{"kind":"stage","id":"stage-3","number":3,"nav":"Thông báo cho cả hai trường hợp","kicker":"CHẶNG 3","title":"Thông báo cho cả hai trường hợp","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Viết if…else","Mỗi dữ liệu đi vào một nhánh"],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Em muốn khách nào cũng thấy kết quả: đủ điều kiện thì nhận quà, còn lại báo chưa đủ.</p></div><p>if…else chọn đúng một trong hai nhánh. Quy tắc vẫn là mua từ 5 ly.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>if (soLy &gt;= 5) {
    cout &lt;&lt; "Nhan qua";
} else {
    cout &lt;&lt; "Chua du";
}</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>Nhập 4 → Chua du
Nhập 5 → Nhan qua</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Sửa dấu so sánh trong chương trình, rồi đối chiếu cả hai nhánh.</p></div>","challenges":[{"id":"s3-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Đúng bằng mốc","prompt":"Khách mua đúng 5 ly. In thông báo nào?","options":[{"text":"Nhan qua"},{"text":"Chua du","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"Nhan qua","why":">= gồm cả bằng 5."},{"id":"s3-debug","type":"code","icon":"⌨️","title":"Đến lượt em: Sửa quy tắc","prompt":"Chương trình đang dùng > 5. Sửa để đơn đúng 5 ly cũng nhận quà.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy;
    cin >> soLy;
    if (soLy > 5) { cout << "Nhan qua"; }
    else { cout << "Chua du"; }
    return 0;
}
","tests":[{"input":"4","expected":"4
Chua du","pureExpected":"Chua du"},{"input":"5","expected":"5
Nhan qua","pureExpected":"Nhan qua"},{"input":"6","expected":"6
Nhan qua","pureExpected":"Nhan qua"}],"inputSpec":{"min":0},"requirements":["Giữ quy tắc mua từ 5 ly."],"hints":["Test case 5 giúp phân biệt > và >=.","Thay > bằng >=."],"why":"Kết quả khớp các test case. Hãy giải thích dòng lệnh em vừa hoàn thiện.","rules":[]}]},{"kind":"stage","id":"stage-4","number":4,"nav":"Kiểm tra quy tắc","kicker":"CHẶNG 4","title":"Kiểm tra quy tắc","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Thử dưới, bằng và trên mốc","Giải thích vì sao cần test case bằng mốc"],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Trước khi phục vụ khách, em kiểm tra chương trình có thực hiện đúng quy ước không.</p></div><p>Chỉ thử 4 và 6 ly thì cả > 5 và >= 5 đều có vẻ đúng. Phải thử thêm đúng 5 ly để phát hiện lỗi.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>// Quy tac: mua tu 5 ly
// Thu 4, 5, 6
// Ket qua can: Chua du, Nhan qua, Nhan qua</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>4 → Chua du
5 → Nhan qua
6 → Nhan qua</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Hoàn thiện chương trình hai nhánh, sau đó giải thích kết quả khi nhập 5.</p></div>","challenges":[{"id":"s4-pick","type":"choice","icon":"🔎","title":"Đọc ví dụ: Test case nào phát hiện lỗi?","prompt":"Một bạn dùng > 5 thay vì >= 5. Cần thử số nào?","options":[{"text":"4","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"5"},{"text":"6","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"5","why":"Hai điều kiện cho kết quả khác nhau tại đúng 5."},{"id":"s4-code","type":"code","icon":"⌨️","title":"Đến lượt em: Hoàn thiện hai nhánh","prompt":"Viết if…else theo quy tắc mua từ 5 ly. Các thông báo dùng đúng mẫu trong bảng.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy;
    cin >> soLy;
    // Tu 5 ly: in Nhan qua
    // Con lai: in Chua du
    return 0;
}
","tests":[{"input":"0","expected":"0
Chua du","pureExpected":"Chua du"},{"input":"4","expected":"4
Chua du","pureExpected":"Chua du"},{"input":"5","expected":"5
Nhan qua","pureExpected":"Nhan qua"},{"input":"6","expected":"6
Nhan qua","pureExpected":"Nhan qua"}],"inputSpec":{"min":0},"requirements":["Dùng if…else."],"hints":["Viết nhánh đủ điều kiện trước.","if (soLy >= 5) { ... } else { ... }"],"why":"Kết quả khớp các test case. Hãy giải thích dòng lệnh em vừa hoàn thiện.","rules":[{"test":(function anonymous(code
) {
return new RegExp("else\b").test(window.CPP.stripComments(code));
}),"msg":"Cần nhánh else cho trường hợp chưa đủ điều kiện."}]}]},{"kind":"boss","id":"boss","number":5,"nav":"Tự kiểm tra","title":"Đơn hàng cuối · Tự kiểm tra","bit":"Em tự làm các nhiệm vụ ngắn bằng kiến thức vừa học. Khi cần, mở gợi ý từng bước.","challenges":[{"id":"boss-1","type":"choice","icon":"🔎","title":"Tự kiểm tra: Chọn nhánh","prompt":"Khách mua 6 ly. Nhánh nào chạy?","code":"if (soLy >= 5) { /* A */ } else { /* B */ }","options":[{"text":"A"},{"text":"B","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"A","why":"6 >= 5 là đúng."},{"id":"boss-2","type":"code","icon":"⌨️","title":"Tự kiểm tra: Sửa điều kiện","prompt":"Quy tắc vẫn là mua từ 5 ly. Sửa lỗi dùng dấu bằng trong điều kiện.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy;
    cin >> soLy;
    if (soLy = 5) { cout << "Nhan qua"; }
    else { cout << "Chua du"; }
    return 0;
}
","tests":[{"input":"4","expected":"4
Chua du","pureExpected":"Chua du"},{"input":"5","expected":"5
Nhan qua","pureExpected":"Nhan qua"}],"inputSpec":{"min":0},"requirements":["Không dùng phép gán làm điều kiện nhận quà."],"hints":["Dấu = thay đổi giá trị của biến.","Điều kiện cần dùng >=."],"why":"Kết quả khớp các test case. Hãy giải thích dòng lệnh em vừa hoàn thiện.","rules":[]},{"id":"boss-3","type":"code","icon":"⌨️","title":"Tự kiểm tra: Phục vụ đơn tiếp theo","prompt":"Hoàn thiện phần xử lý với quy tắc đã học.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy; cin >> soLy;
    // Viet if...else
    return 0;
}
","tests":[{"input":"1","expected":"1
Chua du","pureExpected":"Chua du"},{"input":"5","expected":"5
Nhan qua","pureExpected":"Nhan qua"},{"input":"8","expected":"8
Nhan qua","pureExpected":"Nhan qua"}],"inputSpec":{"min":0},"requirements":["In Nhan qua hoặc Chua du."],"hints":["Nhớ xét đúng bằng mốc 5.","Dùng if (soLy >= 5)."],"why":"Kết quả khớp các test case. Hãy giải thích dòng lệnh em vừa hoàn thiện.","rules":[]},{"id":"adv-1","type":"choice","icon":"🔎","title":"Thử thêm: Chọn test case","prompt":"Muốn phát hiện lỗi bỏ sót trường hợp bằng mốc, nên chọn bộ dữ liệu nào?","options":[{"text":"Chỉ hai số lớn hơn mốc","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"Một số dưới mốc, đúng mốc, một số trên mốc"}],"answer":"Một số dưới mốc, đúng mốc, một số trên mốc","why":"Ba vị trí cho biết quy tắc có xử lý đúng ranh giới hay không.","advanced":true},{"id":"adv-2","type":"choice","icon":"🔎","title":"Thử thêm: Dùng dữ liệu mới","prompt":"Chương trình đúng với ví dụ 3 ly. Điều gì giúp kiểm tra chương trình dùng được cho khách tiếp theo?","options":[{"text":"Giữ nguyên 3 và chạy lại nhiều lần","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"Thử 0, 1 và số lượng khác, dự đoán rồi so kết quả"}],"answer":"Thử 0, 1 và số lượng khác, dự đoán rồi so kết quả","why":"Đổi dữ liệu giúp phát hiện chương trình in sẵn đáp án hoặc dùng số cố định.","advanced":true}]}]};
/* Short explanations and syntax before each worked example. */
(()=>{
  const {cuPhap,codeVaManHinh}=window.KIT;
  const syntax={
    2:[
      {ten:'KHAI BÁO BIẾN',mau:['‹kiểu dữ liệu› ‹tên biến›;','‹kiểu dữ liệu› ‹tên biến› = ‹giá trị ban đầu›;'],phan:[['‹kiểu dữ liệu›','Loại giá trị cần lưu, ví dụ int hoặc double.'],['‹tên biến›','Tên em đặt để dùng lại giá trị.']],quyTac:['Khai báo trước khi dùng.','Khởi tạo hoặc nhập giá trị trước khi tính hay in.']},
      {ten:'NHẬP VÀO BIẾN',mau:'cin >> ‹tên biến›;',phan:[['>>','Đọc dữ liệu và lưu vào biến đã khai báo.']],viDu:'int soLy;
cin >> soLy;',quyTac:['Ô nhập chỉ gõ dữ liệu, ví dụ 3.','Bài này yêu cầu số nguyên không âm.']},
      {ten:'TÍNH VÀ LƯU KẾT QUẢ',mau:'‹tên biến› = ‹biểu thức›;',phan:[['=','Tính vế phải rồi lưu kết quả vào biến bên trái.'],['+  -  *','Cộng, trừ, nhân.']],viDu:'int thanhTien = giaLy * soLy;'},
      {ten:'XUẤT CHỮ VÀ GIÁ TRỊ',mau:['cout << "‹lời giải thích›" << ‹tên biến›;','cout << ‹giá trị› << endl;'],phan:[['<<','Đưa nội dung ra màn hình.'],['endl','Xuống dòng.']],quyTac:['Chữ nằm trong nháy kép. Tên biến nằm ngoài nháy kép.']}
    ],
    3:[
      {ten:'VIẾT ĐIỀU KIỆN',mau:'‹giá trị 1› ‹phép so sánh› ‹giá trị 2›',viDu:'soLy >= 5',phan:[['>=','Lớn hơn hoặc bằng: tính cả đúng mốc.'],['==','Bằng nhau. Khác dấu = dùng để gán.']]},
      {ten:'LỆNH IF',mau:'if (‹điều kiện›) {
    ‹lệnh khi điều kiện đúng›;
}',quyTac:['Không đặt ; ngay sau if (...).','Lệnh sau dấu } vẫn được thực hiện.']},
      {ten:'HAI NHÁNH IF…ELSE',mau:'if (‹điều kiện›) {
    ‹lệnh khi đúng›;
} else {
    ‹lệnh khi sai›;
}',quyTac:['Mỗi lần kiểm tra chỉ chạy một trong hai nhánh.']},
      {ten:'ĐỐI CHIẾU ĐIỀU KIỆN VỚI QUY TẮC',mau:'soLy >= 5',phan:[['Từ 5 ly','Dùng >= 5, gồm cả đúng 5.']],quyTac:['Thử 4, 5, 6 để kiểm tra dưới, bằng và trên mốc.']}
    ],
    4:[
      {ten:'LẶP MỘT VIỆC',mau:'for (int i = 1; i <= 3; i++) {
    ‹việc cần lặp›;
}',phan:[['int i = 1','Bắt đầu đếm từ 1.'],['i <= 3','Còn đúng thì tiếp tục.'],['i++','Sau mỗi lượt, tăng i thêm 1.']]},
      {ten:'DÙNG BIẾN ĐẾM',mau:'for (int i = 1; i <= 5; i++) {
